import React from "react";
import { useParams } from "react-router-dom";
import products from "../data/products";
import { useCart } from "../context/CartContext";

// ✅ Toast import
import { toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";

const ProductDetail = () => {
  const { id } = useParams();
  const { addToCart } = useCart();

  const product = products.find((p) => p.id === parseInt(id));

  if (!product)
    return <h2 style={{ textAlign: "center" }}>Product Not Found</h2>;

  // ✅ ADD TO CART WITH POPUP
  const handleAddToCart = () => {
    addToCart(product);
    toast.success("Added to cart 🛒", {
      position: "top-right",
      autoClose: 2000,
    });
  };

  return (
    <div
      style={{
        padding: "60px 20px",
        minHeight: "100vh",
        background: "linear-gradient(135deg, #fff1f8, #f0fbff)",
      }}
    >
      <div
        style={{
          maxWidth: "1100px",
          margin: "auto",
          display: "flex",
          gap: "60px",
          flexWrap: "wrap",
          alignItems: "center",
          background: "white",
          padding: "35px",
          borderRadius: "25px",
          boxShadow: "0 20px 50px rgba(0,0,0,0.1)",
        }}
      >
        {/* IMAGE */}
        <div style={{ flex: "1" }}>
          <img
            src={product.image}
            alt={product.name}
            style={{
              width: "100%",
              borderRadius: "20px",
              transition: "0.3s",
            }}
          />
        </div>

        {/* DETAILS */}
        <div style={{ flex: "1" }}>
          <h1
            style={{
              color: "#d63384",
              fontSize: "32px",
              marginBottom: "10px",
            }}
          >
            {product.name}
          </h1>

          <p
            style={{
              fontSize: "22px",
              margin: "10px 0",
              fontWeight: "600",
              color: "#ff4f87",
            }}
          >
            ₹{product.price}
          </p>

          <p style={{ color: "#666", marginBottom: "10px" }}>
            Age: {product.age || "Not specified"}
          </p>

          <p
            style={{
              marginTop: "15px",
              lineHeight: "1.7",
              color: "#444",
            }}
          >
            This beautiful handmade product is made with love 💖.
            Perfect for your little one. Soft, comfortable and stylish.
          </p>

          {/* BUTTON */}
          <button
            onClick={handleAddToCart}
            style={{
              marginTop: "30px",
              padding: "14px 30px",
              border: "none",
              borderRadius: "30px",
              background: "linear-gradient(135deg, #ff4f87, #ff85a2)",
              color: "white",
              fontSize: "16px",
              cursor: "pointer",
              fontWeight: "600",
              boxShadow: "0 10px 25px rgba(0,0,0,0.2)",
            }}
          >
            Add to Cart 🛒
          </button>
        </div>
      </div>
    </div>
  );
};

export default ProductDetail;
